// Düğmeyle servo: potansiyometrenin açısını servoya aktar.
#include <Servo.h>  // Arduino IDE ile gelir

const int POT_PIN = A0;
const int SERVO_PIN = 9;

Servo servo;

void setup() {
  Serial.begin(9600);
  servo.attach(SERVO_PIN);
}

void loop() {
  int deger = analogRead(POT_PIN);          // 0-1023
  int aci = map(deger, 0, 1023, 0, 180);    // 0-180 derece
  servo.write(aci);
  Serial.println(aci);
  delay(15);
}
